window.__rgjRes=null; window.__rgjErr=null;
(async () => { try {
  const out = {};
  const probe = async (u) => {
    const t = await (await fetch(u)).text();
    const d = new DOMParser().parseFromString(t,'text/html');
    const links = [...d.querySelectorAll('a[href*="/game/"]')].map(a=>[a.getAttribute('href'), (a.textContent||'').trim()]).slice(0,8);
    return { len: t.length, n: d.querySelectorAll('a[href*="/game/"]').length, links, title: d.title };
  };
  out.search = await probe('https://retroachievements.org/gameSearch.php?q=Super%20Mario%20Bros.%203');
  await new Promise(r=>setTimeout(r,4000));
  out.list = await probe('https://retroachievements.org/gameList.php?system=7');
  out.list2 = await probe('https://retroachievements.org/gameList.php?system=7&page=2');
  window.__rgjRes = JSON.stringify(out);
} catch(e){ window.__rgjErr = String(e && e.stack || e); } })();
